package vn.gk.logistics.payments;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import vn.gk.logistics.dispatch.WorkDayPolicy;
import java.time.*;
import java.util.*;
@RestController
public class VehicleCostController {
 private final JdbcTemplate jdbc;private final WorkDayPolicy policy;
 public VehicleCostController(JdbcTemplate jdbc,WorkDayPolicy policy){this.jdbc=jdbc;this.policy=policy;}
 private Map<?,?> user(HttpServletRequest req){var u=(Map<?,?>)req.getAttribute("user");if(u==null||!Set.of("driver","dispatcher").contains(u.get("role")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return u;}
 private void conflict(String s){throw new ResponseStatusException(HttpStatus.CONFLICT,s);}
 @GetMapping({"/api/vehicle-costs","/api/driver/vehicle-costs"}) public List<Map<String,Object>> list(@RequestParam(required=false) Long id,HttpServletRequest req){var u=user(req);var conditions=new ArrayList<String>();var args=new ArrayList<Object>();if("driver".equals(u.get("role"))){conditions.add("r.driver_id=?");args.add(u.get("driver_id"));}if(id!=null){conditions.add("r.id=?");args.add(id);}return jdbc.queryForList("SELECT r.*,v.code AS vehicle,v.plate,d.name AS driver FROM vehicle_cost_receipts r JOIN vehicles v ON v.id=r.vehicle_id LEFT JOIN drivers d ON d.id=r.driver_id"+(conditions.isEmpty()?"":" WHERE "+String.join(" AND ",conditions))+" ORDER BY CASE r.status WHEN 'pending' THEN 0 ELSE 1 END,r.id DESC LIMIT 200",args.toArray());}
 @PostMapping({"/api/vehicle-costs","/api/driver/vehicle-costs"}) @Transactional public Map<String,Object> create(@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req);jdbc.execute("SELECT pg_advisory_xact_lock(7462014)");long amount;int vid;UUID request;try{amount=new java.math.BigDecimal(b.get("amount").toString()).longValueExact();vid=new java.math.BigDecimal(b.get("vehicleId").toString()).intValueExact();request=UUID.fromString(b.get("requestId").toString());}catch(Exception e){throw new IllegalArgumentException("Nhập đúng xe, số tiền và mã phiếu");}if(amount<1||amount>1000000000)throw new IllegalArgumentException("Số tiền từ 1 đến 1 tỷ đồng");String kind=Objects.toString(b.get("kind"),"fuel"),description=Objects.toString(b.get("description"),"").strip(),reference=Objects.toString(b.get("reference"),"").strip();LocalDate day;try{day=LocalDate.parse(b.get("date").toString());}catch(Exception e){throw new IllegalArgumentException("Ngày chứng từ không hợp lệ");}if(!Set.of("fuel","other").contains(kind)||description.length()<3||description.length()>500||reference.length()>120||day.isAfter(policy.today())||day.isBefore(LocalDate.of(2026,9,1)))throw new IllegalArgumentException("Kiểm tra loại phiếu, nội dung, ngày và chứng từ");boolean driver="driver".equals(u.get("role"));Integer did=driver?((Number)u.get("driver_id")).intValue():null;if(driver&&(day.isBefore(policy.today().minusDays(7))||jdbc.queryForObject("SELECT count(*) FROM vehicles v WHERE v.id=? AND (EXISTS(SELECT 1 FROM drivers d WHERE d.id=? AND d.vehicle_id=v.id) OR EXISTS(SELECT 1 FROM trips t WHERE t.vehicle_id=v.id AND t.driver_id=? AND t.planned_start::date>=?))",Integer.class,vid,did,did,policy.today().minusDays(7))==0))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Chỉ lập phiếu cho xe được giao trong 7 ngày gần đây");var existing=jdbc.queryForList("SELECT body::text,result::text,created_by FROM finance_requests WHERE id=?",request);String signature=vid+":"+amount+":"+kind+":"+day+":"+description+":"+reference;if(!existing.isEmpty()){var row=existing.get(0);String saved=jdbc.queryForObject("SELECT body->>'signature' FROM finance_requests WHERE id=?",String.class,request);if(!signature.equals(saved)||!Objects.equals(((Number)row.get("created_by")).longValue(),((Number)u.get("id")).longValue()))conflict("Mã phiếu đã dùng với nội dung khác");Long id=jdbc.queryForObject("SELECT (result->>'id')::bigint FROM finance_requests WHERE id=?",Long.class,request);return Map.of("id",id);}
  var v=jdbc.queryForMap("SELECT warehouse_id FROM vehicles WHERE id=?",vid);Long id=jdbc.queryForObject("INSERT INTO vehicle_cost_receipts(vehicle_id,driver_id,warehouse_id,cost_date,kind,amount,description,reference,created_by) VALUES(?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,vid,did,v.get("warehouse_id"),day,kind,amount,description,reference,u.get("id"));jdbc.update("INSERT INTO finance_requests(id,kind,body,result,created_by) VALUES(?,'vehicle-cost',jsonb_build_object('signature',?::text),jsonb_build_object('id',?::bigint),?)",request,signature,id,u.get("id"));jdbc.update("INSERT INTO vehicle_cost_events(receipt_id,action,user_id,note) VALUES(?,'created',?,?)",id,u.get("id"),description);jdbc.update("INSERT INTO dispatcher_notifications(source_key,type,level,title,message,href,warehouse_id) VALUES(?,'vehicle_cost_submitted','info','Phiếu chi phí xe chờ duyệt',?,'/maintenance',?)","vehicle-cost:"+id,"Phiếu #"+id+" · "+amount+" đ",v.get("warehouse_id"));return Map.of("id",id);}
 @PostMapping("/api/vehicle-costs/{id}/{action}") @Transactional public Map<String,Object> review(@PathVariable long id,@PathVariable String action,@RequestBody Map<String,Object>b,HttpServletRequest req){var u=user(req);if(!"dispatcher".equals(u.get("role")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);jdbc.execute("SELECT pg_advisory_xact_lock(7462014)");if("cancel".equals(action))conflict("Phiếu đã xử lý chỉ được xem, không được hủy");if(!Set.of("approve","reject").contains(action))throw new IllegalArgumentException("Thao tác không hợp lệ");var r=jdbc.queryForMap("SELECT * FROM vehicle_cost_receipts WHERE id=? FOR UPDATE",id);String reason=Objects.toString(b.get("reason"),"").strip();if(reason.length()>400||!action.equals("approve")&&reason.length()<3)throw new IllegalArgumentException("Nhập lý do từ 3 đến 400 ký tự");String target=action.equals("approve")?"approved":"rejected";if(target.equals(r.get("status")))return Map.of("status",target);if(!"pending".equals(r.get("status")))conflict("Phiếu không còn ở trạng thái cho phép");if(action.equals("approve"))jdbc.update("INSERT INTO finance_entries(source_key,entry_date,direction,category,amount,warehouse_id,vehicle_id,driver_id,description,reference,vehicle_receipt_id,created_by,is_demo) VALUES(?,?,'expense',?,?,?,?,?,?,?,?,?,?)","vehicle-cost:"+id,r.get("cost_date"),r.get("kind").equals("fuel")?"fuel":"maintenance",r.get("amount"),r.get("warehouse_id"),r.get("vehicle_id"),r.get("driver_id"),r.get("description"),r.get("reference"),id,u.get("id"),r.get("is_demo"));jdbc.update("UPDATE vehicle_cost_receipts SET status=?,reviewed_by=?,reviewed_at=now(),review_note=? WHERE id=?",target,u.get("id"),reason,id);jdbc.update("INSERT INTO vehicle_cost_events(receipt_id,action,user_id,note) VALUES(?,?,?,?)",id,target,u.get("id"),reason);if(r.get("driver_id")!=null)jdbc.update("INSERT INTO driver_notifications(driver_id,source_key,type,title,message) VALUES(?,?,'vehicle_cost_reviewed',?,?)",r.get("driver_id"),"vehicle-cost:"+id+":"+target,"Phiếu chi phí xe đã "+(action.equals("approve")?"được duyệt":action.equals("reject")?"bị từ chối":"được hủy"),"Phiếu #"+id+" · "+r.get("amount")+" đ · "+reason);return Map.of("status",target);}
}
